        """Add a record to the end of the queue."""
        self.queue.append(record)

    def dequeue(self):
        """Remove and return the next record from the queue."""
        if self.queue:
            return self.queue.pop(0)
        else:
            return None

    def get_next_record(self):
        """Return the next record from the queue without removing it."""
        if self.queue:
            return self.queue[0]
        else:
            return None

    def get_next_record_labels(self):
        """Return the labels corresponding to the next record in the queue."""
        if self.queue:
            return self.queue[0][1]
        else:
            return None

    def get_next_record_labels_sequence(self):
        """Return the labels corresponding to the next record in the queue as a sequence."""
        if self.queue:
            return [label for label in self.queue[0][1]]
        else:
            return None

    def is_empty(self):
        """Return True if the queue is empty."""
        return len(self.queue) == 0

    def size(self):
        """Return the number of records in the queue."""
        return len(self.queue)

    def get_size(self):
