    # Define the graph of functions and dependencies
    graph = gr.Graph()
    graph.add_node('func1')
    graph.add_node('func2')
    graph.add_node('func3')
    graph.add_node('func4')
    graph.add_edge('func1', 'func2')
    graph.add_edge('func2', 'func4')
    graph.add_edge('func1', 'func3')
    graph.add_edge('func3', 'func4')

    # Create a call dispatcher
    dispatcher = CallDispatcher(graph)

    # Dispatch a call to the function 'func1' with arguments 'arg1' and 'arg2'
    dispatcher.dispatch_call('func1', 'arg1', 'arg2')
