        pdf_writer = PdfFileWriter()
        pdf_writer.addPage(PdfFileReader(pdf_file_obj)..getPage(0).extractText())
        pdf_writer.addPage(PdfFileReader(open(content, 'rb')).getPage(0).extractText())
