class SExpression:
    def __init__(self):
        self.value = None

    def set_value(self, value):
        self.value = value

    def __eq__(self, other):
        if isinstance(other, SExpression):
            return self.value == other.value
        return False

    def __repr__(self):
        return f"SExpression(value={self.value})"

class SExpressionEmulator:
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(SExpression())

    def pop(self):
        if self.stack:
            return self.stack.pop()
        return None

    def evaluate(self, expr):
        if expr.type == 'list':
            for item in expr.value:
                self.evaluate(item)
        elif expr.type == 'pair':
            if self.stack and self.stack[-1].value == expr.left and self.stack[-2].value == expr.right:
                self.push(SExpression(expr.left, expr.right))
            else:
                raise ValueError(f"Invalid pair: {expr}")
        elif expr.type == 'symbol':
            if expr.value in ['+', '-', '*', '/', '**', 'eq', 'neq', 'lt', 'gt', 'le', 'ge']:
                self.push(SExpression(expr.value))
            else:
                raise ValueError(f"Invalid symbol: {expr}")
        elif expr.type == 'number':
            self.push(SExpression(expr.value))
        elif expr.type == 'paren':
            self.evaluate(expr.left)
            self.evaluate(expr.right)
        else:
            raise ValueError(f"Unsupported expression type: {expr.type}")

    def __repr__(self):
        return str(self.stack)

