        try:
            self.cursor.execute("DELETE FROM data WHERE key = ?", (key,))
            self.conn.commit()
            self._release_lock()
        except sqlite3.OperationalError:
            self._release_lock()
        except KeyError:
            self._release_lock()
            return False
        return True

    def get_keys(self):
        self._acquire()
        try:
            return [row[0] for row in self.data.values()]
        except KeyError:
            self._release_lock()
            return []
        finally:
