import functools

def retry(max_attempts=3, callback=None):
    """
    A decorator function that retries a given function up to a specified number of times.

    Args:
        max_attempts (int): The maximum number of attempts to make before giving up. Defaults to 3.
        callback (function): A function that will be called after each attempt. Defaults to None.

    Returns:
        function: A function that can be called with a retry decorator.
    """

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt < max_attempts - 1:
                        print(f"Attempt {attempt + 1} failed. Retrying in 1 second...")
                        time.sleep(1)
                    else:
                        print(f"All {max_attempts} attempts failed. Giving up.")
                        raise e
        return wrapper
    return decorator

