        pair = df.iloc[idx]

        # check if the pair is in the set v
        if pair not in v:
            clusters.append(pair)
            v.remove(pair)

        # try to add the pair to one of the existing clusters
        for cluster in clusters:
            if set(pair).issubset(set(cluster)):
                cluster.add(pair)
                break

        # if no valid cluster is found, start a new one
