def get_regex(patterns):
    def group_prefixes(pattern):
        groups = []
        current_group = ''
        for char in pattern:
            if char.isupper():
                if current_group:
                    groups.append(current_group)
                current_group = char
            elif char == '_':
                if current_group:
                    groups.append(current_group)
                current_group = ''
            else:
