#include <algorithm>

int main() {
    // Create a vector of opaque data types with a run-time record length
    std::vector<void*> data(100 * 50);

    // Generate random data for testing
    std::random_device rd;
    std::mt19937_64 gen(rd());
    std::uniform_int_distribution<> dis(0, 255);
    for (int i = 0; i < 100; ++i) {
        for (int j = 0; j < 50; ++j) {
            data[i * 50 + j] = static_cast<void*>(dis(gen));
        }
    }

    // Define a custom comparator
    auto cmp = [](void* a, void* b) {
        int* a_val = static_cast<int*>(a);
        int* b_val = static_cast<int*>(b);
        return *(int*)a_val < *(int*)b_val;
    };

    // Sort the data using the custom comparator
    std::sort(data.begin(), data.end(), cmp);

    // Print the sorted data
    for (int i = 0; i < 100 * 50; ++i) {
        std::cout << *static_cast<int*>(data[i]) << " ";
    }
    std::cout << std::endl;

    return 0;
}
